// Attached documents (files.js): the complete extracted text of each file, sent with every turn
// while attached. The same character cap is enforced in the browser, so nothing is cut silently.
const DOCUMENT_LIMIT=250000;
const KIND_LABEL={pdf:"PDF",docx:"Word document",csv:"CSV file",text:"text"};
function documentBlock(documents){
  const parts=documents.map((d,i)=>{const words=(d.text.trim().match(/\S+/g)||[]).length;const size=[d.pages?`${d.pages} page${d.pages===1?"":"s"}`:"",`${words} words`].filter(Boolean).join(", ");return `Document ${i+1}: "${d.name}" (${KIND_LABEL[d.kind]}, ${size}). Its complete text is between the markers.\n<<<DOCUMENT ${i+1} START>>>\n${d.text.replace(/<<<DOCUMENT/g,"<<DOCUMENT")}\n<<<DOCUMENT ${i+1} END>>>`});
  return `ATTACHED DOCUMENTS (added by the user with the + button; they stay attached for this chat until removed):\n\n${parts.join("\n\n")}`;
}

// Things to do together (offers): four are picked at random each turn and suggested first, so
